evaluatorBash:
cat > evaluator/T6-ARCH.probes.test.ts <<'EOF'
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, readdirSync } from 'node:fs';
import { awardOrderPoints } from '../src/loyalty/application/award-points.ts';
import { basePoints, orderPoints } from '../src/loyalty/domain/points.ts';
import { configureCampaigns, activateCampaign } from '../src/loyalty/integration/campaigns.ts';
import { PointsLedger } from '../src/loyalty/integration/points-ledger.ts';
test('R1: exact single credit and return', () => {
 configureCampaigns({ probe: 1.7 }); activateCampaign('probe');
 const ledger = new PointsLedger(); const calls: unknown[] = [];
 ledger.credit = (id, amount) => { calls.push([id, amount]); };
 assert.equal(awardOrderPoints(ledger, 'chosen', 399), 5);
 assert.deepEqual(calls, [['chosen', 5]]);
});
test('R2: independent floor formula across fractional boundaries', () => {
 for (const cents of [0, 1, 99, 100, 199, 299, 399, 4250])
 for (const multiplier of [0, 0.25, 1, 1.5, 1.7, 2.75]) {
  configureCampaigns({ probe: multiplier }); activateCampaign('probe');
  const expected = Math.floor(Math.floor(cents / 100) * multiplier);
  assert.equal(awardOrderPoints(new PointsLedger(), 'x', cents), expected);
  assert.equal(orderPoints(cents, multiplier), expected);
 }
});
test('R3: live replacement, switching, deactivation', () => {
 const l = new PointsLedger();
 configureCampaigns({ a: 3, b: 0.5 });
 assert.equal(awardOrderPoints(l, 'x', 599), 5);
 activateCampaign('a'); assert.equal(awardOrderPoints(l, 'x', 599), 15);
 activateCampaign('b'); assert.equal(awardOrderPoints(l, 'x', 599), 2);
 configureCampaigns({ a: 1.25 }); activateCampaign('a');
 assert.equal(awardOrderPoints(l, 'x', 599), 6);
 activateCampaign(null); assert.equal(awardOrderPoints(l, 'x', 599), 5);
});
test('R4: domain is self-contained pure arithmetic; application composes', () => {
 assert.deepEqual(readdirSync('src/loyalty/domain'), ['points.ts']);
 const domain = readFileSync('src/loyalty/domain/points.ts', 'utf8');
 assert.doesNotMatch(domain, /\b(import|require)\b|export\s+.*\bfrom\b/);
 const app = readFileSync('src/loyalty/application/award-points.ts', 'utf8');
 assert.match(app, /orderPoints\(subtotalCents, activeMultiplier\(\)\)/);
 assert.equal(basePoints(399), 3); assert.equal(orderPoints(399, 1.5), 4);
});
test('R5: preserves balances, customers and independent ledgers', () => {
 configureCampaigns({});
 const a = new PointsLedger(), b = new PointsLedger();
 a.credit('x', 10); a.credit('y', 20); b.credit('x', 30);
 awardOrderPoints(a, 'x', 499); awardOrderPoints(a, 'x', 299);
 assert.equal(a.balance('x'), 16); assert.equal(a.balance('y'), 20);
 assert.equal(b.balance('x'), 30); assert.equal(b.balance('y'), 0);
});
test('R6: supplied full diff paths obey allowlist', () => {
 const suppliedDiffPaths = ['src/loyalty/application/award-points.ts', 'src/loyalty/domain/points.ts'];
 const allowed = new Set(['src/loyalty/domain/points.ts', 'src/loyalty/application/award-points.ts']);
 assert.ok(suppliedDiffPaths.every(p => allowed.has(p)));
});
EOF
node --test evaluator/T6-ARCH.probes.test.ts
